package com.nexuszero.mt.core;import java.util.*;public final class DiffEngine{private DiffEngine(){}public static String diff(String a,String b){Set<String>A=new LinkedHashSet<>(Arrays.asList(a.split("\\r?\\n"))),B=new LinkedHashSet<>(Arrays.asList(b.split("\\r?\\n"))),add=new LinkedHashSet<>(B),del=new LinkedHashSet<>(A);add.removeAll(A);del.removeAll(B);StringBuilder o=new StringBuilder("NEXUS DIFF\n");for(String x:add)if(hit(x))o.append("+ ").append(x).append('\n');for(String x:del)if(hit(x))o.append("- ").append(x).append('\n');return o.toString();}static boolean hit(String x){String l=x.toLowerCase(Locale.ROOT);return l.contains("http")||l.contains("socket")||l.contains("event")||l.contains(".method")||l.contains(".class")||l.contains("api");}}